// Route Hongqi reading links generated by the archive templates to its actual chapters.
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const h=a.getAttribute('href')||'';if(/^#(?:read|topic)\/hongqi(?:\/|$)/.test(h)){e.preventDefault();e.stopImmediatePropagation();location.href='hongqi.html?chapter=ca71'}},true);
